int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info)
{
    struct hwsim_new_radio_params params = { 0 };
    int ret = 0;

    if (info->attrs[HWSIM_ATTR_REGULATORY_STRICTNESS]) {
        params.regulatory_strictness =
            nla_get_u8(info->attrs[HWSIM_ATTR_REGULATORY_STRICTNESS]);
    }

    if (info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE]) {
        params.support_p2p_device =
            nla_get_u8(info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE]);
    }

    if (info->attrs[HWSIM_ATTR_CHANNELS]) {
        params.channels = nla_get_u32(info->attrs[HWSIM_ATTR_CHANNELS]);
    }

    if (info->attrs[HWSIM_ATTR_RADIO_NAME]) {
        params.radio_name = nla_strdup(info->attrs[HWSIM_ATTR_RADIO_NAME], GFP_KERNEL);
        if (!params.radio_name) {
            return -ENOMEM;
        }
    }

    if (info->attrs[HWSIM_ATTR_REGULATORY_ALPHA2]) {
        nla_strscpy(params.alpha2, info->attrs[HWSIM_ATTR_REGULATORY_ALPHA2], sizeof(params.alpha2));
    }

    if (info->attrs[HWSIM_ATTR_CUSTOM_REG_DOMAIN]) {
        params.regd_idx = nla_get_u32(info->attrs[HWSIM_ATTR_CUSTOM_REG_DOMAIN]);
    }

    ret = mac80211_hwsim_new_radio(&params);

    if (params.radio_name) {
        kfree(params.radio_name);
    }

    return ret;
}

int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info)
{
    struct hwsim_new_radio_params params = {};
    int ret = -EINVAL;
    char *custom_name = NULL;

    if (!info)
        return -EINVAL;

    /* Initialize default values */
    params.strict_reg = false;
    params.no_irq = false;
    params.p2p_dev_support = false;

    /* Parse and set attributes */
    if (info->attrs[HWSIM_ATTR_REGULATORY_STRICTNESS]) {
        u8 strictness;

        if (nla_get_u8(info->attrs[HWSIM_ATTR_REGULATORY_STRICTNESS]))
            params.strict_reg = true;
    }

    if (info->attrs[HWSIM_ATTR_NO_IR])
        params.no_irq = true;

    if (info->attrs[HWSIM_ATTR_P2P_DEV])
        params.p2p_dev_support = true;

    if (info->attrs[HWSIM_ATTR_CHANNELS]) {
        u8 channels = nla_get_u8(info->attrs[HWSIM_ATTR_CHANNELS]);

        if (channels <= HWSIM_MAX_CHANNELS)
            params.channels = channels;
        else
            return -EINVAL;
    }

    if (info->attrs[HWSIM_ATTR_RADIO_NAME]) {
        custom_name = nla_data(info->attrs[HWSIM_ATTR_RADIO_NAME]);
        params.name = custom_name;
    }

    if (info->attrs[HWSIM_ATTR_REGULATORY_DOMAIN]) {
        u16 idx = nla_get_u16(info->attrs[HWSIM_ATTR_REGULATORY_DOMAIN]);

        if (idx < HWSIM_MAX_REGDOM)
            params.regdom_idx = idx;
        else
            return -EINVAL;
    }

    ret = mac80211_hwsim_new_radio(&params);
    if (ret < 0)
        return ret;

    return ret;
}
